// Target directories
const targetDirs = [
  path.join(__dirname, 'sourashtra'),
  path.join(__dirname, '..', 'backend', 'data'),
  path.join(__dirname, '..', 'mobile', 'src', 'data')
];

for (const dir of targetDirs) {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  fs.writeFileSync(path.join(dir, 'verified_seed_words.json'), JSON.stringify(ALL_WORDS, null, 2), 'utf8');
  console.log(`✅ Synced verified words (${ALL_WORDS.length} items) to: ${dir}`);
}

